<?= $this->extend('layouts/admin') ?><?= $this->section('content') ?>
<div class="page"><div class="page-heading"><div><p class="eyebrow">CATALOG</p><h1>Products</h1><p>Manage product details, availability, and images.</p></div></div>
<?php if (session('error')): ?><p role="alert"><?= esc(session('error')) ?></p><?php endif ?><?php if (session('success')): ?><p role="status"><?= esc(session('success')) ?></p><?php endif ?>
<form class="admin-form filter-form" action="<?= site_url('admin/products') ?>" method="get"><label>Search products<input name="q" type="search" value="<?= esc($query) ?>" placeholder="Product name"></label><label>Category<select name="category"><option value="">All categories</option><?php foreach ($categories as $categoryOption): ?><option value="<?= esc($categoryOption['id']) ?>" <?= (string) $categoryOption['id'] === $category ? 'selected' : '' ?>><?= esc($categoryOption['name']) ?></option><?php endforeach ?></select></label><button type="submit">Search</button></form>
<?php $renderForm = static function ($product, $categories) { ?><form class="admin-form" action="<?= site_url('admin/products' . ($product ? '/' . $product['id'] : '')) ?>" method="post" enctype="multipart/form-data"><?= csrf_field() ?><label>Name<input name="name" value="<?= esc($product['name'] ?? '') ?>" required></label><label>Slug<input name="slug" value="<?= esc($product['slug'] ?? '') ?>" required></label><label>Category<select name="category_id" required><?php foreach ($categories as $category): ?><option value="<?= esc($category['id']) ?>" <?= (int) ($product['category_id'] ?? 0) === (int) $category['id'] ? 'selected' : '' ?>><?= esc($category['name']) ?></option><?php endforeach ?></select></label><label>Description<textarea name="description"><?= esc($product['description'] ?? '') ?></textarea></label><label>Price (IDR)<input name="price" type="number" step="0.01" min="0" value="<?= esc($product['price'] ?? '') ?>" required></label><label>Stock<input name="stock" type="number" min="0" step="1" value="<?= esc($product['stock'] ?? 0) ?>" required></label><label>Status<select name="status"><option value="active">Active</option><option value="inactive" <?= ($product['status'] ?? '') === 'inactive' ? 'selected' : '' ?>>Inactive</option></select></label><label>Image (JPEG, PNG, or WebP, max 2 MB)<input name="image" type="file" accept="image/jpeg,image/png,image/webp"></label><button type="submit">Save product</button></form><?php }; ?>
<details class="admin-item add-item"><summary>Add product</summary><?php $renderForm(null, $categories) ?></details>
<div class="section-heading"><div><p class="eyebrow">YOUR CATALOG</p><h2>Product list</h2></div></div>
<?php if (! $products): ?><div class="empty-state"><strong>No products found</strong><p>Try a different search or category.</p></div><?php endif ?>
<?php foreach ($products as $product): ?><details class="admin-item"><summary><span><strong><?= esc($product['name']) ?></strong><span class="item-meta"><?= esc(ucfirst($product['status'])) ?> · <?= esc($product['stock']) ?> in stock · <?= format_rupiah((string) $product['price']) ?></span></span></summary><?php $renderForm($product, $categories) ?><form action="<?= site_url('admin/products/' . $product['id'] . '/toggle') ?>" method="post" onsubmit="return confirm('Change this status?')"><?= csrf_field() ?><button class="button-secondary" type="submit"><?= $product['status'] === 'active' ? 'Deactivate' : 'Activate' ?></button></form></details><?php endforeach ?>
<div class="pagination"><?= $pager->links() ?></div></div><?= $this->endSection() ?>
